customMethods.script:
system.perspective.print("getLogs() called")

import os
from java.io import RandomAccessFile
from java.nio.file import Files, Paths
from java.util.concurrent import Executors, TimeUnit, TimeoutException
from jarray import zeros

lines = int(payload.get("lines", 500))
which = int(payload.get("which", 0))            # 0 => wrapper.log, 1 => wrapper.log.1, etc.
maxBytes = int(payload.get("maxBytes", 1024 * 512))    # default 512KB

fileSep = system.util.getProperty("file.separator")
osName = system.util.getProperty("os.name") or ""
ignitionHome = system.util.getProperty("ignition.home")

def getRotatedPath(basePath):
	if which <= 0:    return basePath
	return basePath + "." + str(which)

candidatePaths = []

if ignitionHome: candidatePaths.append(ignitionHome + fileSep + "logs" + fileSep + "wrapper.log")

candidatePaths.append(r"C:\Program Files\Inductive Automation\Ignition\logs\wrapper.log")
candidatePaths.append(r"C:\Program Files (x86)\Inductive Automation\Ignition\logs\wrapper.log")

candidatePaths.append("/usr/local/bin/ignition/logs/wrapper.log")
candidatePaths.append("/usr/local/ignition/logs/wrapper.log")
candidatePaths.append("/opt/ignition/logs/wrapper.log")
candidatePaths.append("/var/log/ignition/wrapper.log")

wrapperPath = None
for basePath in candidatePaths:
	p = getRotatedPath(basePath)
	if system.file.fileExists(p):
		wrapperPath = p
		break

if wrapperPath is None:
	containerNote = ""
	if "Linux" in osName and system.file.fileExists("/.dockerenv"):
		containerNote = ("\n\nNote: This Gateway appears to be running in a container. "
			"Official Ignition container images typically send wrapper output to stdout, "
			"so wrapper.log may not exist on disk. Use docker/k8s logs instead.")

	checked = "\n".join([getRotatedPath(p) for p in candidatePaths])
	return {"text": "wrapper.log not found. Checked:\n" + checked + containerNote}

def isStreamSymlink(path):
	try:
		p = Paths.get(path)
		if not Files.isSymbolicLink(p):
			return False
		target = str(Files.readSymbolicLink(p)).lower()
		return ("/proc/" in target or "fd/1" in target or "fd/2" in target
			or "stdout" in target or "stderr" in target or "/dev/console" in target)
	except:
		return False

if isStreamSymlink(wrapperPath):
	return {"text": "=== " + wrapperPath + " ===\n"
		"This path is a symlink to the container's stdout stream, not a real log file. "
		"It has no fixed end, so reading it here would block indefinitely waiting for "
		"new output. Use `docker logs --tail " + str(lines) + "` or "
		"`kubectl logs --tail " + str(lines) + "` instead."}

def readChunk(raf, chunkSize):
	buf = zeros(chunkSize, 'b')
	numRead = raf.read(buf)
	if numRead == -1:
		return None
	if numRead < chunkSize:
		buf = buf[:numRead]
	return "".join([chr(b & 0xFF) for b in buf])

def tailFileSeekable(raf, maxBytes):
	length = raf.length()
	start = max(0, length - maxBytes)
	raf.seek(start)

	size = int(length - start)
	buf = zeros(size, 'b')
	raf.readFully(buf)
	return "".join([chr(b & 0xFF) for b in buf])

def tailFileSequential(raf, maxBytes):
	chunkSize = 65536
	tail = ""
	while True:
		chunk = readChunk(raf, chunkSize)
		if chunk is None:
			break
		tail += chunk
		if len(tail) > maxBytes * 2:
			tail = tail[-maxBytes:]
	return tail[-maxBytes:] if len(tail) > maxBytes else tail

def runWithTimeout(fn, timeoutSeconds):
	executor = Executors.newSingleThreadExecutor()
	try:
		future = executor.submit(fn)
		try:
			return future.get(timeoutSeconds, TimeUnit.SECONDS)
		except TimeoutException:
			future.cancel(True)
			raise
	finally:
		executor.shutdownNow()

def tailFileText(path, maxBytes):
	raf = RandomAccessFile(path, "r")
	try:
		try:
			return tailFileSeekable(raf, maxBytes), True
		except:
			pass    # not seekable (pipe/device/symlink to stdout) - fall through below
	finally:
		raf.close()

	# Reopen fresh rather than reusing/reseeking raf: seek(0) on a non-seekable
	# descriptor throws "Illegal seek" too, so we must never call seek() here at all.
	raf2 = RandomAccessFile(path, "r")
	try:
		result = runWithTimeout(lambda: tailFileSequential(raf2, maxBytes), 5)
		return result, False
	finally:
		raf2.close()    # closing while the background read is blocked forces it to throw, unsticking that thread

try:
	text, wasSeekable = tailFileText(wrapperPath, maxBytes)
	textLines = text.splitlines()
	tailLines = "\n".join(textLines[-lines:])

	header = "=== " + wrapperPath + " ==="
	if not wasSeekable:
		header += ("\n(Note: this path is not a regular seekable file — likely a symlink to "
			"the container's stdout. Read sequentially instead of tailed by byte offset; "
			"for guaranteed-complete history prefer `docker logs`/`kubectl logs`.)")

	return {"text": header + "\n" + tailLines}
except TimeoutException:
	system.perspective.print("Error: timeout")
	return {"text": "=== " + wrapperPath + " ===\n"
		"Reading this path did not finish within 5s — it is likely an active stream "
		"with no end, not a regular file. Use `docker logs`/`kubectl logs` instead."}
except:
	import sys
	return {"text": "Error reading wrapper log: " + str(sys.exc_info()[1])}
